function confirmTargetLoadout(){if(targetLoadoutSelection.length!==4||new Set(targetLoadoutSelection).size!==4)return;personaRuntime.initializeLoadout(targetLoadoutSelection.map(id=>({templateId:id,instanceId:`BASE_INSTANCE_${id}`,source:'BASE_PERSONA'})),{generatedAtNodeId:'TARGET_PERSONA_SELECT',generatedAtBattleIndexCompat:0,source:'BASE_PERSONA'});globalThis.runController.updateRunResult({initialPersonaTemplateIds:[...targetLoadoutSelection]});updateTargetMetrics(metrics=>{metrics.personaEquipHistory.push({nodeId:'TARGET_PERSONA_SELECT',action:'INITIAL_LOADOUT',equippedPersonaInstanceIds:personaRuntime.getState().equippedPersonaInstanceIds,timestamp:Date.now()});metrics.rawEvents.push({type:'PERSONA_LOADOUT_CONFIRMED',nodeId:'TARGET_PERSONA_SELECT',templateIds:[...targetLoadoutSelection],timestamp:Date.now()})});globalThis.runController.setNodeRuntime({selectedTemplateIds:[...targetLoadoutSelection],confirmed:true});$('#target-loadout-dialog').close();globalThis.runController.completeNode({type:'PERSONA_LOADOUT_CONFIRMED',nodeId:'TARGET_PERSONA_SELECT',templateIds:[...targetLoadoutSelection]})}
function renderPersonaGrowth(){const runtimeState=personaRuntime.getState(),instance=runtimeState.personaInstancesById[currentGrowthInstanceId],template=instance&&personaRuntime.getTemplate(instance.templateId);if(!template)return;const feedback=globalThis.PersonaFeedback.cardView(template,instance.runtimeState);$('#persona-growth-card').innerHTML=`<h3>${template.name}</h3><p>${template.tags.join(' · ')}</p><dl class="growth-guidance"><div><dt>怎么玩</dt><dd>${feedback.playHint}</dd></div><div><dt>怎么触发</dt><dd>${feedback.trigger}</dd></div><div><dt>触发后</dt><dd>${feedback.reward}</dd></div><div><dt>当前状态</dt><dd>${feedback.status.join(' · ')}</dd></div></dl><small>${feedback.preciseRule}</small>`;$('#persona-growth-slots').innerHTML=runtimeState.equippedPersonaInstanceIds.map((id,index)=>{const equipped=id&&runtimeState.personaInstancesById[id],equippedTemplate=equipped&&personaRuntime.getTemplate(equipped.templateId);return`<button data-growth-slot="${index}" class="${growthSelectedSlot===index?'selected':''}"><b>槽位 ${index+1}</b><br><span>${equippedTemplate?.name||'空位'}</span></button>`}).join('');document.querySelectorAll('[data-growth-slot]').forEach(button=>button.onclick=()=>{growthSelectedSlot=Number(button.dataset.growthSlot);renderPersonaGrowth()});$('#persona-growth-keep').classList.toggle('hidden',!isTargetRun())}
function openPersonaGrowth(persist=true,restoring=false){const node=currentStageNode(),profile=personaGrowthProfileById.get(node?.growthProfileId),runtimeData=globalThis.runController.getCurrentRuntime()?.data||{};currentGrowthInstanceId=runtimeData.generatedPersonaInstanceId||null;if(!currentGrowthInstanceId){const instance=personaRuntime.createInstance(profile.templateId,{source:profile.source,generatedAtNodeId:node.id,generatedAtBattleIndexCompat:globalThis.runController.getState().battleIndexCompat});currentGrowthInstanceId=instance.instanceId;globalThis.runController.setNodeRuntime({generatedPersonaInstanceId:instance.instanceId});updateTargetMetrics(metrics=>{if(!metrics.generatedPersonaInstanceIds.includes(instance.instanceId))metrics.generatedPersonaInstanceIds.push(instance.instanceId);metrics.rawEvents.push({type:'PERSONA_GENERATED',nodeId:node.id,instanceId:instance.instanceId,templateId:instance.templateId,timestamp:Date.now()})})}growthSelectedSlot=0;renderPersonaGrowth();const dialog=$('#persona-growth-dialog');if(!dialog.open)dialog.showModal();if(persist)window.commitRunSave?.('persona_growth',restoring?'persona_growth_restored':'persona_growth_generated')}
function completeTargetGrowth(action,slotIndex=null){const node=currentStageNode(),runtime=globalThis.runController.getCurrentRuntime();updateTargetMetrics(metrics=>{metrics.growthNodeDurationMs[node.id]=Math.max(0,Date.now()-(runtime?.enteredAt||Date.now()));metrics.personaEquipHistory.push({nodeId:node.id,action,generatedPersonaInstanceId:currentGrowthInstanceId,slotIndex,equippedPersonaInstanceIds:personaRuntime.getState().equippedPersonaInstanceIds,timestamp:Date.now()});metrics.rawEvents.push({type:'PERSONA_GROWTH_DECISION',nodeId:node.id,action,instanceId:currentGrowthInstanceId,slotIndex,timestamp:Date.now()})});$('#persona-growth-dialog').close();globalThis.runController.completeNode({type:'PERSONA_GROWTH_COMPLETED',nodeId:node.id,instanceId:currentGrowthInstanceId,action,slotIndex})}
