function buildTargetReport(){const metrics=globalThis.runController.getRunMetrics(),runtimeState=personaRuntime.getState(),battleNodes=currentBattleNodeSequence(),last=metrics.battleScores.at(-1),completed=last?.nodeId==='N13'&&last.win;metrics.totalRunDurationMs=Math.max(0,Date.now()-globalThis.runController.getState().runStartedAt);globalThis.runController.updateRunMetrics(metrics);globalThis.runController.updateRunResult({completed,finalNodeId:last?.nodeId||null});$('#target-report-summary').innerHTML=`<article><small>通关状态</small><strong>${completed?'已通关':'未通关'}</strong></article><article><small>累计得分</small><strong>${metrics.runTotalScore}</strong></article><article><small>最高单手</small><strong>${metrics.maxSingleHandScore}</strong></article><article><small>用时</small><strong>${Math.round(metrics.totalRunDurationMs/1000)} 秒</strong></article>`;$('#target-report-battles').innerHTML=battleNodes.map((node,index)=>{const item=metrics.battleScores.find(entry=>entry.nodeId===node.id);return`<article><b>战斗 ${String(index+1).padStart(2,'0')}</b><span>${item?`${item.score} / ${item.targetScore} · ${item.win?'胜':'败'}`:'未进入'}</span></article>`}).join('');$('#target-report-personas').innerHTML=runtimeState.runPersonaPool.map(id=>{const instance=runtimeState.personaInstancesById[id],template=instance&&personaRuntime.getTemplate(instance.templateId),triggers=metrics.personaTriggersByInstance[id]||0;return`<article><b>${template?.name||'未命名人格'}</b><small>${runtimeState.equippedPersonaInstanceIds.includes(id)?'当前装备':'未装备'} · 触发 ${triggers} 次</small></article>`}).join('')}
function openTargetReport(persist=true){window.showBattleFromRoute?.();buildTargetReport();if(!$('#target-report-dialog').open)$('#target-report-dialog').showModal();if(persist)window.commitRunSave?.('target_report','target_report_opened')}
