function renderTargetCarry(){const metrics=globalThis.runController.getRunMetrics(),state=personaRuntime.getState(),ids=metrics.generatedPersonaInstanceIds.filter(id=>state.personaInstancesById[id]);$('#target-carry-options').innerHTML=ids.map(id=>{const instance=state.personaInstancesById[id],template=personaRuntime.getTemplate(instance.templateId),nodeLabel=/^N\d+$/.test(instance.generatedAtNodeId||'')?`节点 ${instance.generatedAtNodeId.slice(1)}`:'成长节点';return`<button data-carry-instance="${id}" class="${targetCarrySelectionId===id?'selected':''}"><h3>${template.name}</h3><small>${nodeLabel}</small><p>${targetEffectCopy(template)}</p></button>`}).join('')||'<p>本局在失败前没有生成人格，允许直接结束。</p>';$('#target-carry-note').textContent=ids.length?`已生成 ${ids.length} 张；只能带出其中 1 张。`:'没有可带出的人格。';$('#target-carry-confirm').disabled=ids.length>0&&!ids.includes(targetCarrySelectionId);$('#target-carry-confirm').textContent=ids.length?'确认带出并结束本局':'结束本局';document.querySelectorAll('[data-carry-instance]').forEach(button=>button.onclick=()=>{targetCarrySelectionId=button.dataset.carryInstance;globalThis.runController.setNodeRuntime({selectedPersonaInstanceId:targetCarrySelectionId});renderTargetCarry()})}
